            ['classroom' => '8º ano', 'student' => 'Vitória Strunkis da Rosa', 'subject' => 'Artes', 'bimester' => 2, 'concept' => 'B'],
        ];

        DB::transaction(function () use ($records, $subjects, $classrooms) {
            foreach ($records as $item) {
                // 1. Valida se a disciplina existe no banco
                $subjectId = $subjects[$item['subject']] ?? null;

                if (!$subjectId) {
                    $this->command->warn("Disciplina não encontrada no banco: {$item['subject']}");
                    continue;
                }

                // 2. Busca o aluno pelo nome
                $student = Student::where('name', $item['student'])->first();

                if (!$student) {
                    $this->command->warn("Aluno não encontrado: {$item['student']}");
                    continue;
                }

                // 3. Obtém o ID da turma
                $classroomId = $classrooms[$item['classroom']]
                    ?? $student->classrooms()->wherePivot('status', 'active')->first()?->id;

                if (!$classroomId) {
                    $this->command->warn("Turma não encontrada para o aluno: {$item['student']}");
                    continue;
                }

                // 4. Insere/Atualiza apenas os bimestres 1 e 2
                BimesterResult::updateOrCreate(
                    [
                        'student_id'   => $student->id,
                        'classroom_id' => $classroomId,
                        'subject_id'   => $subjectId,
                        'bimester'     => $item['bimester'],
                    ],
                    [
                        'concept'      => $item['concept'],
                    ]
                );
            }
        });

        $this->command->info('Lançamentos do 1º e 2º bimestres importados com sucesso!');
    }
